SELECT COUNT(*) FROM T_MITARBEITER WHERE AGT_ID IN (
    SELECT AGT_ID FROM T_AGENTUR WHERE AGT_ID IN (
        SELECT AGT_ID FROM T_DECKUNG WHERE ERSTDAT = (SELECT MAX(ERSTDAT) FROM T_DECKUNG)
    )
)

SELECT VORNAME, NAME FROM T_MITARBEITER WHERE AGT_ID IN (
    SELECT AGT_ID FROM T_VERTRAG WHERE STAT_CD = 'AKT'
) ORDER BY SUM(BETRAG) DESC LIMIT 1;

SELECT MA_NAME, NAME FROM T_MITARBEITER WHERE AGT_ID IN (
    SELECT AGT_ID FROM T_VERTRAG WHERE STAT_CD = 'AKT'
)
ORDER BY SUM(T_VERTRAG.SELBSTBEH) DESC
LIMIT 1;

SELECT M_NAME, VORNAME FROM T_MITARBEITER WHERE AGT_ID IN (
    SELECT LEITER_MA_ID FROM T_AGENTUR WHERE STAT_CD = 'AKT'
) GROUP BY M_NAME, VORNAME ORDER BY COUNT(*) DESC LIMIT 1

SELECT M vorname, N FROM T_MITARBEITER WHERE AGT_ID IN (SELECT AGT_ID FROM T_VERTRAG WHERE STAT_CD = 'AKT')
ORDER BY SUM(VZWW_CD) DESC
LIMIT 1;

SELECT SUM(JPRAEMIE) FROM T_SCHADEN WHERE VTR_ID IN (
    SELECT VTR_ID FROM T_VERTRAG WHERE STAT_CD = 'AKT' AND T_PARTNER.STAT_CD IN ('WERKST', 'DRITT')
    INTERSECT ALL
    SELECT VTR_ID FROM T_VERTRAG WHERE STAT_CD = 'AKT' AND T_PARTNER.STAT_CD = 'KUNDE'
)
AND T_PARTNER.REGION = 'Deutschschweiz' AND YEAR(T_PARTNER.GEB_DAT) = 2025;

SELECT SUM(T_SCH_ZLG.BETRAG) AS Schadenzahl
FROM T_SCH_ZLG
WHERE T_SCH_ZLG.BETRAG IS NULL AND T_SCH_ZLG.MAHNSTUFE = 0;

